    """Write a field, putting multi-line values on continuation lines."""
    if "\n" not in value:
        lines.append(f"- {key}: {value}")
    else:
        first, rest = value.split("\n", 1)
        lines.append(f"- {key}: {first}")
        for cont in rest.split("\n"):
            lines.append(cont)


